// ═══════════════════════════════════════════════════════════════════════════
// THE GOLD GAME — RETRO 2D build (same .holo, second modality).
//
// PROMOTED (I.017 gate 4): the playable retro 2D build is now GENERATED by the
// native Canvas2DGameCompiler (packages/core/src/compiler/Canvas2DGameCompiler.ts)
// from the SAME parsed gold-vault-game.holo the 3D Drive build walks — the
// hand-written renderer is retired. Gameplay is DERIVED FROM TRAITS
// (@controllable=player, @grabbable=collectible, @collidable=hazard,
// @dialogue=goal, environment.gravity, spatial_group origins=tiers), not coded
// by hand. Output is a self-contained NES-ish 320x288 pixel-canvas game (limited
// palette, scanlines, fixed-timestep loop, physics/collision, WebAudio, score +
// localStorage, START/WIN/LOSE) that opens by double-clicking index.html offline.
//
// The embedded SCENE stays byte-identical to the 3D build's source and the scene
// digest is still computed via the REAL packages/engine computeStateDigest over
// that source scene only — so One .holo -> two modalities (D.007) holds and the
// 2D/3D builds provably derive from the identical source scene.
//
//   node_modules/.bin/tsx examples/gold-game/gold-2d-build.mjs
// Outputs: examples/gold-game/2d-build/{index.html, START-HERE.txt}
//          examples/gold-game/GOLD-VAULT-2D-receipt.json
// ═══════════════════════════════════════════════════════════════════════════

import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, join, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(
  process.env.HOLOSCRIPT_REPO || process.env.HOLOSCRIPT_ROOT || join(here, '..', '..')
);
const imp = (p) => import(pathToFileURL(p).href);
const { computeStateDigest } = await imp(
  join(repo, 'packages', 'engine', 'src', 'simulation', 'hashes.ts')
);
const core = await imp(join(repo, 'packages', 'core', 'dist', 'index.js'));
const { compileCanvas2DGame } = await imp(
  join(repo, 'packages', 'core', 'src', 'compiler', 'Canvas2DGameCompiler.ts')
);
const parseHolo = core.parseHolo;

const HOLO = join(here, 'gold-vault-game.holo');
const OUT = join(here, '2d-build');
const HASH_MODE = 'sha256';
const prop = (node, key, dflt) => {
  const p = (node?.properties || []).find((x) => x.key === key);
  return p ? p.value : dflt;
};

// ── 1. Parse the real .holo (same Gate 0 artifact the 3D build uses) ─────────
const src = readFileSync(HOLO, 'utf8');
const r = parseHolo(src);
if (!r.success || (r.errors || []).length) {
  console.error('PARSE FAILED', r.errors);
  process.exit(1);
}
const ast = r.ast || r.composition || r;
const templates = Object.fromEntries((ast.templates || []).map((t) => [t.name, t]));

// ── 2. Walk composition -> flat scene (SAME extraction as drive-build.mjs) ───
const add = (arr, v) => (Array.isArray(v) ? v : [0, 0, 0]).map((n, i) => n + (arr[i] || 0));
const meshes = [];
for (const g of ast.spatialGroups || []) {
  const origin = prop(g, 'origin', [0, 0, 0]);
  for (const o of g.objects || []) {
    const tpl = templates[o.template] || {};
    const geometry = prop(o, 'geometry', prop(tpl, 'geometry', 'box'));
    const scale = prop(o, 'scale', prop(tpl, 'scale', [1, 1, 1]));
    const color = prop(o, 'color', '#cccccc');
    const pos = add(origin, prop(o, 'position', [0, 0, 0]));
    const st = o.state || {};
    meshes.push({
      name: o.name,
      region: g.name,
      geometry,
      position: pos,
      scale,
      color,
      tier: st.tier || null,
      title: st.title || null,
      inhabited_by: st.inhabited_by || null,
    });
  }
}
const regions = (ast.spatialGroups || []).map((g) => ({
  name: g.name,
  origin: prop(g, 'origin', [0, 0, 0]),
}));
const scene = { title: ast.name || 'GOLD — The Vault', meshes, regions };
const sceneJson = JSON.stringify(scene);

// ── 3. Deterministic scene digest via the REAL contract fn (shared with 3D) ──
// Encode the scene numerically so the SAME .holo always yields the SAME digest.
const colInt = (h) => parseInt((h || '#000000').replace('#', '').slice(0, 6), 16) || 0;
const sceneSolver = {
  fieldNames: ['scene'],
  getField: () =>
    Float32Array.from(
      meshes.flatMap((m) => [
        ...m.position.map((n) => Number(n.toFixed(4))),
        colInt(m.color),
        m.geometry.length,
      ])
    ),
};
const sceneDigest = computeStateDigest(sceneSolver, HASH_MODE);

// ── 4. Normalize AST -> flat composition, then COMPILE (trait-driven) ────────
// (properties -> direct fields; template traits resolved per object). The same
// shape Canvas2DGameCompiler consumes; gameplay is derived from traits.
const normComposition = {
  name: ast.name || 'GOLD — The Vault',
  templates: (ast.templates || []).map((t) => ({
    name: t.name,
    traits: (t.traits || []).map((tr) => ({ name: tr.name, config: tr.config || {} })),
  })),
  spatialGroups: (ast.spatialGroups || []).map((g) => ({
    name: g.name,
    origin: prop(g, 'origin', [0, 0, 0]),
    objects: (g.objects || []).map((o) => ({
      name: o.name,
      template: o.template,
      position: prop(o, 'position', [0, 0, 0]),
      color: prop(o, 'color', '#cccccc'),
      state: o.state || {},
      traits: (o.traits || []).map((tr) => ({ name: tr.name, config: tr.config || {} })),
    })),
  })),
  environment: {
    gravity: prop(ast.environment, 'gravity', [0, -9.81, 0]),
    timeLimit: prop(ast.environment, 'timeLimit', undefined),
    startingHearts: prop(ast.environment, 'startingHearts', undefined),
    muteDefault: prop(ast.environment, 'muteDefault', undefined),
    musicVolume: prop(ast.environment, 'musicVolume', undefined),
    sfxVolume: prop(ast.environment, 'sfxVolume', undefined),
    musicTempo: prop(ast.environment, 'musicTempo', undefined),
  },
};

const html = compileCanvas2DGame(
  normComposition,
  { title: 'THE GOLD GAME — The Vault' },
  sceneJson
);

// ── 5. Emit the build + receipt ──────────────────────────────────────────────
rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });
writeFileSync(join(OUT, 'index.html'), html);
writeFileSync(
  join(OUT, 'START-HERE.txt'),
  'THE GOLD GAME — retro 2D build (playable, compiled from HoloScript traits)\nDouble-click index.html (offline, no install).\nA/D or arrows move, SPACE/W jump, M mute, R restart.\nClimb the tiers, grab every knowledge gem, reach the Archivist before the timer.\nGenerated by Canvas2DGameCompiler from the same gold-vault-game.holo as the 3D build.\n'
);

const receipt = {
  modality: '2d-retro',
  name: 'THE GOLD GAME — retro 2D build (compiled from traits, second modality)',
  source: 'examples/gold-game/gold-vault-game.holo',
  builder: 'examples/gold-game/gold-2d-build.mjs',
  compiler: 'packages/core/src/compiler/Canvas2DGameCompiler.ts (compileCanvas2DGame)',
  artifact: 'examples/gold-game/2d-build/index.html',
  renderer:
    'compiler-generated by Canvas2DGameCompiler — gameplay derived from traits (@controllable/@grabbable/@collidable/@dialogue, environment.gravity, spatial_group tiers); pure HTML5 canvas, 320x288 internal, nearest-neighbor upscale, 16-color palette + scanlines, fixed-timestep loop, one-way-platform physics/collision, WebAudio SFX + ambient, particle/screen-shake juice, score + localStorage high score, START/WIN/LOSE objective (no external deps; opens on file://)',
  contract: {
    spine: 'REAL computeStateDigest from packages/engine/src/simulation/hashes.ts',
    function: 'computeStateDigest(sceneSolver, hashMode)',
    algorithm: HASH_MODE,
    sceneDigest,
    sceneFields: 'per-mesh [posX,posY,posZ, colorInt, geometryNameLen]',
    meshCount: meshes.length,
    reproducible:
      'run `node_modules/.bin/tsx examples/gold-game/gold-2d-build.mjs` to re-derive sceneDigest',
  },
  oneSourceTwoModalities: {
    note: 'this 2D build and the 3D Drive build (drive-build.mjs -> drive-build/index.html) walk the IDENTICAL parsed gold-vault-game.holo; the sceneDigest below is the shared deterministic source-scene fingerprint.',
    holoParsesClean: true,
  },
  honestScope:
    'The 2D build is now COMPILED FROM TRAITS by the native Canvas2DGameCompiler — the hand-written renderer is retired (I.017 gate 4). The compiler classifies each entity by its effective traits (player=@controllable, collectible=@grabbable, hazard=@collidable-only, goal=@dialogue, npc=@ai_agent), reads environment.gravity, and treats spatial_group origins as ascending tier platforms, emitting a generic runtime that consumes the derived spec — NOT a 1:1 hardcode (proven by Canvas2DGameCompiler.test.ts on a second composition). The embedded SCENE is byte-identical to the source the 3D build walks and the sceneDigest is computed over that source scene ONLY, so One .holo -> two modalities (D.007) holds. The build does NOT re-implement the flagship server-side curation/graduation verb (Gates 3/6/15); the shared pure control-logic module gold-game-controls.mjs remains the Gate-15 contract. Verified by opening index.html (offline, file://); this receipt proves the source scene + digest reproduce deterministically and the artifact is emitted.',
  builtAt: new Date().toISOString(),
};
writeFileSync(join(here, 'GOLD-VAULT-2D-receipt.json'), JSON.stringify(receipt, null, 2) + '\n');

console.log('2D RETRO BUILD EMITTED (compiled) ->', join(OUT, 'index.html'));
console.log('  meshes=' + meshes.length, 'sceneDigest=' + sceneDigest);
